```python
from flask import Flask, request, jsonify

app = Flask(__name__)

def convert_temp(temperature):
    try:
        # Convert the input string to a float
        fahrenheit = float(temperature)
        # Convert Fahrenheit to Celsius
        celsius = (fahrenheit - 32) * 5 / 9
        # Round to two decimal places
        return round(celsius, 2)
    except ValueError:
        # Handle the case where the input is not a valid number
        return None

@app.route('/convert', methods=['POST'])
def convert():
    data = request.json
    temperature_str = data.get('temperature')
    converted_temp = convert_temp(temperature_str)

    if converted_temp is not None:
        return jsonify({
            'temperature_in_celsius': converted_temp
        }), 200
    else:
        return jsonify({
            'error': 'Invalid input. Please provide a valid temperature string.'
        }), 400

if __name__ == '__main__':
    app.run(debug=True)
```

