    def _validate_amount(self, amount):
        if not isinstance(amount, (int, float, decimal.Decimal)):
            raise ValueError("The principal amount must be a number.")
        return decimal.Decimal(amount)

    def _validate_rate(self, rate):
        if not isinstance(rate, (int, float, decimal.Decimal)):
            raise ValueError("The interest rate must be a number.")
        return decimal.Decimal(rate)

    def _validate_time(self, time):
        if not isinstance(time, (int, float, decimal.Decimal)) or time <= 0:
            raise ValueError("The time period must be a positive number.")
        return decimal.Decimal(time)

    def _validate_compounding_periods(self, periods):
        if not isinstance(periods, int) or periods <= 0:
            raise ValueError("Compounding periods must be a positive integer.")
        return periods

    def _validate_fee(self, fee):
        if not isinstance(fee, (int, float, decimal.Decimal)):
            raise ValueError("Fee must be a number.")
        return decimal.Decimal(fee)

    def _validate_schedule(self, schedule):
        if not isinstance(schedule, list):
            raise ValueError("The interest rate schedule must be a list.")
        for rate in schedule:
            self._validate_rate(rate)

    def _calculate_compound_interest(self):
        if self.interest_type == 'simple':
            return self.principal * (1 + (self.interest_rate / self.compounding_periods) * self.time_period)
        else:  # compound interest
            return self.principal * ((1 + (self.interest_rate / self.compounding_periods)) ** (self.compounding_periods * self.time_period))

    def calculate_future_value(self):
        total_interest = self._calculate_compound_interest() - self.principal
        total_fees = self.fee * self.time_period if self.fee else decimal.Decimal(0)
        return self.principal + total_interest - total_fees

    def calculate_initial_investment(self, future_value):
        future_value = self._validate_amount(future_value)
        return future_value / self._calculate_compound_interest()

    def calculate_effective_annual_interest_rate(self):
        if self.interest_type == 'simple':
            return self.interest_rate
        else:
            return ((1 + (self.interest_rate / self.compounding_periods)) ** self.compounding_periods) - 1

    def calculate_total_amount_with_fees(self):
        return self.calculate_future_value() + (self.fee * self.time_period)

    def calculate_time_to_achieve_future_value(self, future_value):
        future_value = self._validate_amount(future_value)
        return (decimal.Decimal(future_value) / self.principal) ** (1 / (self.interest_rate / self.compounding_periods)) / self.time_period

    def calculate_interest_earned(self):
        return self.calculate_future_value() - self.principal

    def calculate_average_interest_rate(self, future_value, time_period):
        future_value = self._validate_amount(future_value)
        time_period = self._validate_time(time_period)
        return (future_value / self.principal) ** (1 / time_period) - 1

    def calculate_compounding_period_to_achieve_future_value(self, future_value):
        future_value = self._validate_amount(future_value)
        return self.time_period * (decimal.Decimal(future_value) / self.principal) ** (1 / self.time_period) - 1

